"""Tests for the CME Daily Bulletin gold source.

Two sets:
  * synthetic -- tests/fixtures/synthetic/*.pdf, generated by
    tests/fixtures/make_synthetic_bulletin.py in the real 2026 layout
    (NOT CME data; always run)
  * real      -- your downloaded PDFs in ./inbox or ./inbox/done (or the
    folder in $GEXMAP_INBOX); skipped with a message when none are present
"""
from __future__ import annotations

import datetime as dt
import os
import shutil
import sys
from pathlib import Path

import numpy as np
import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "tests" / "fixtures"))

import bulletin_gold as bg  # noqa: E402
import cme_gold as cg  # noqa: E402
import gexmap  # noqa: E402

FIX = ROOT / "tests" / "fixtures" / "synthetic"
BOOK_KEYS = {"kref", "k", "S", "T", "iv", "oi", "call", "q", "exp", "S_ref", "asof", "session"}
META_KEYS = {"ref_ticker", "tv_ref", "hi", "lo", "iv_fallback", "stamps"}
QUIET = dict(log=lambda *_: None)


def _real_inputs():
    best = {}
    for c in (os.environ.get("GEXMAP_INBOX"), ROOT / "inbox", ROOT / "inbox" / "done"):
        if c and Path(c).is_dir():
            for sec, (p, td) in bg.find_inputs(c).items():
                if sec not in best or td > best[sec][1]:
                    best[sec] = (p, td)
    return best


@pytest.fixture(scope="module", params=["synthetic", "real"])
def inputs(request):
    if request.param == "synthetic":
        found = bg.find_inputs(FIX)
        assert {"s64", "s62", "s02b"} <= set(found), "run tests/fixtures/make_synthetic_bulletin.py"
    else:
        found = _real_inputs()
        if not {"s64", "s62"} <= set(found):
            pytest.skip("no real Section 62 + 64 PDFs in ./inbox or ./inbox/done "
                        "(download them from the CME Daily Bulletin)")
    return request.param, found


@pytest.fixture(scope="module")
def loaded(inputs):
    kind, found = inputs
    s02b = found.get("s02b")
    if s02b and s02b[1] != found["s64"][1]:
        s02b = None
    book, meta = bg.build_book(found["s64"][0], found["s62"][0], gexmap.next_session,
                               s02b[0] if s02b else None, **QUIET)
    return kind, found, book, meta


def test_more_than_500_gold_option_rows(loaded):
    _, found, _, meta = loaded
    rows, diag = bg.parse_options(found["s64"][0])
    assert len(rows) > 500, f"only {len(rows)} gold option rows"
    assert not diag["unparsed"], diag["unparsed"][:3]
    assert meta["stamps"]["rows_parsed"] == len(rows)


def test_block_totals_match(loaded):
    _, found, _, _ = loaded
    rows, diag = bg.parse_options(found["s64"][0])
    assert diag["totals"], "no TOTAL lines found"
    for (fam, sub, ym), tot in diag["totals"].items():
        got = sum(np.nan_to_num(r.oi) for r in rows if r.family == fam and r.ym == ym
                  and (r.cp == sub if isinstance(sub, str) else r.weekday == sub))
        assert got == tot, (fam, sub, ym, got, tot)


def test_strikes_within_15pct_of_futures(loaded):
    _, _, book, _ = loaded
    rel = book["kref"] / book["S_ref"] - 1.0
    assert len(rel) > 0
    assert np.all(np.abs(rel) <= 0.15 + 1e-12)


def test_every_series_maps_to_gc_future(loaded):
    _, found, _, meta = loaded
    futs, _ = bg.parse_futures(found["s62"][0])
    tickers = {cg.gc_ticker(*k) for k in futs}
    assert meta["stamps"]["series"]
    for name, (_, fut) in meta["stamps"]["series"].items():
        assert fut.startswith("GC") and fut in tickers, f"{name} -> {fut}"
    # put-call parity forward agrees with the mapped future for labelled series
    for name, (imp, fut, F) in meta["stamps"]["parity"].items():
        assert abs(imp / F - 1) <= bg.PARITY_TOL, (name, imp, fut, F)


def test_total_oi_matches_section_02b(loaded):
    _, found, _, meta = loaded
    if "s02b" not in found or found["s02b"][1] != found["s64"][1]:
        pytest.skip("no Section 02B PDF for the same trade date")
    rows, _ = bg.parse_options(found["s64"][0])
    parsed = sum(np.nan_to_num(r.oi) for r in rows)
    summary = bg.parse_02b_gold_options_oi(found["s02b"][0])
    assert summary > 0
    assert abs(parsed - summary) / summary <= 0.02, f"parsed {parsed:,.0f} vs 02B {summary:,.0f}"


def test_weekly_classification_vs_02b(loaded):
    _, found, _, meta = loaded
    st = meta["stamps"]
    if st["weekly_miss"] is None:
        pytest.skip("no Section 02B to check the weekly classification against")
    weekly = sum(b for k, (a, b) in st["weekly_check"].items() if k.startswith("G"))
    print(f"weekly OI off 02B: model {st['weekly_miss_model']:,.0f}, balanced {st['weekly_miss']:,.0f} "
          f"of {weekly:,.0f}")
    assert st["weekly_miss_model"] <= 0.10 * weekly
    assert st["weekly_miss"] <= 0.01 * weekly


def test_delta_sanity(loaded):
    _, _, _, meta = loaded
    print(f"median |Black-76 delta - bulletin delta| = {meta['stamps']['delta_mad']:.4f}")
    assert meta["stamps"]["delta_mad"] <= bg.DELTA_MAD_MAX


def test_book_contract(loaded):
    _, found, book, meta = loaded
    assert set(book) == BOOK_KEYS
    assert set(meta) == META_KEYS
    n = len(book["k"])
    for k in ("kref", "k", "S", "T", "iv", "oi", "call", "q", "exp"):
        assert isinstance(book[k], np.ndarray) and book[k].shape == (n,), k
    assert book["call"].dtype == bool
    td = found["s64"][1]
    assert book["exp"].min() > td.toordinal()                       # front expiry after trade date
    assert np.all(book["T"] >= cg.YEAR_MIN - 1e-15)                  # 30-minute floor
    assert book["session"] == gexmap.next_session(td)
    assert meta["tv_ref"] == cg.tv_symbol(meta["ref_ticker"], td.year)
    assert meta["lo"] <= book["S_ref"] <= meta["hi"]


def test_levels_line(loaded):
    _, _, book, meta = loaded
    lv = gexmap.compute_levels(gexmap.fill_iv(book, meta), meta)
    line = gexmap.fmt_line("XAUUSD", lv)
    print(line)
    for tag in ("CW", "PW", "walls", "HVL", "GW", "MP", "0DTE C", "VU", "VD", "regime", "bias"):
        assert tag in line
    assert lv["VD"] < book["S_ref"] < lv["VU"]


# ---------------------------------------------------------------- synthetic-only
def test_synthetic_reference_expiries_and_exclusions():
    found = bg.find_inputs(FIX)
    book, meta = bg.build_book(found["s64"][0], found["s62"][0], gexmap.next_session, **QUIET)
    assert meta["ref_ticker"] == "GCZ6" and meta["tv_ref"] == "COMEX:GCZ2026"
    assert book["S_ref"] == 4000.0                     # not the 1OZ / MGC rows
    s = meta["stamps"]["series"]
    assert s["OG 2026-11-24"] == ("OG", "GCZ6")
    assert s["OG 2026-12-28"] == ("OG", "GCG7")        # Jan options exercise into Feb futures
    assert s["OG4 2026-11-27"] == ("OG4", "GCG7")      # after the Dec OG expiry
    assert s["G1R 2026-11-05"] == ("GWR", "GCZ6")
    assert dt.date.fromordinal(int(book["exp"].min())) == dt.date(2026, 11, 5)
    rows, diag = bg.parse_options(found["s64"][0])
    assert {r.family for r in rows} == {"OG", "OG1", "OG2", "OG3", "OG4", "GWR"}   # no OMG/SO/EOO
    assert any("MICRO" in t for t in diag["skipped_titles"])
    g7 = book["S"] != book["S_ref"]
    assert g7.any()
    np.testing.assert_allclose(book["kref"][g7], book["k"][g7] * book["S_ref"] / book["S"][g7])


def test_synthetic_weekly_classification_is_exact_without_02b():
    import make_synthetic_bulletin as mk
    found = bg.find_inputs(FIX)
    _, meta = bg.build_book(found["s64"][0], found["s62"][0], gexmap.next_session,
                            found["s02b"][0], **QUIET)
    assert meta["stamps"]["weekly_miss_model"] == 0
    truth = mk.build(FIX.parent / "_tmp_truth")      # regenerates the same seed
    shutil.rmtree(FIX.parent / "_tmp_truth")
    for k, (mine, _) in meta["stamps"]["weekly_check"].items():
        code, cp = k.split()
        assert mine == truth[(code, cp)], k


def test_zero_rows_is_an_error():
    found = bg.find_inputs(FIX)
    with pytest.raises(bg.BulletinError, match="zero gold option rows"):
        bg.build_book(found["s62"][0], found["s62"][0], gexmap.next_session, **QUIET)


def test_total_line_mismatch_is_an_error(monkeypatch):
    found = bg.find_inputs(FIX)
    real = bg.parse_options

    def drop_one(path):
        rows, d = real(path)
        rows = [r for r in rows if not (r.family == "OG" and r.cp == "C" and r.strike == 4000)]
        return rows, d

    monkeypatch.setattr(bg, "parse_options", drop_one)
    with pytest.raises(bg.BulletinError, match="TOTAL"):
        bg.build_book(found["s64"][0], found["s62"][0], gexmap.next_session, **QUIET)


def test_strikes_far_from_futures_is_an_error(monkeypatch):
    found = bg.find_inputs(FIX)
    real = bg.parse_options

    def scaled(path):
        rows, d = real(path)
        for r in rows:
            r.strike *= 10      # e.g. strikes printed with implied decimals
        return rows, d

    monkeypatch.setattr(bg, "parse_options", scaled)
    with pytest.raises(bg.BulletinError, match="parity|not clustered"):
        bg.build_book(found["s64"][0], found["s62"][0], gexmap.next_session, **QUIET)


def test_missing_pdfs_skip_xauusd(tmp_path, capsys):
    rc = gexmap.main(["--inbox", str(tmp_path), "--out", str(tmp_path / "o.pine")])
    out = capsys.readouterr().out
    assert rc == 1 and "XAUUSD  skipped" in out and not (tmp_path / "o.pine").exists()


def test_full_pipeline_moves_files(tmp_path, capsys):
    inbox = tmp_path / "inbox"
    shutil.copytree(FIX, inbox)
    out = tmp_path / "gamma_map.pine"
    assert gexmap.main(["--inbox", str(inbox), "--out", str(out)]) == 0
    txt = capsys.readouterr().out
    print(txt)
    assert "XAUUSD" in txt and "CW " in txt and "HVL " in txt and "SYNTHETIC" in txt
    pine = out.read_text()
    assert pine.startswith("//@version=6") and 'input.symbol("COMEX:GCZ2026"' in pine
    assert not list(inbox.glob("*.pdf")) and len(list((inbox / "done").glob("*.pdf"))) == 3


def test_newest_trade_date_wins(tmp_path):
    import make_synthetic_bulletin as mk
    mk.build(tmp_path, dt.date(2026, 11, 3))
    mk.build(tmp_path, dt.date(2026, 11, 4))
    found = bg.find_inputs(tmp_path)
    assert {s: td for s, (_, td) in found.items()} == {
        "s64": dt.date(2026, 11, 4), "s62": dt.date(2026, 11, 4), "s02b": dt.date(2026, 11, 4)}


def test_row_and_total_parsing():
    t = "3600 ---- ---- 11.70B/4.10A 11.70B/4.10A ---- 3.70 NEW .0316 ---- ---- 10 ---- 10 + 10".split()
    assert bg._parse_tail(t[1:]) == (3.7, 0.0316, np.nan, 10.0, 10.0) or bg._parse_tail(t[1:])[0] == 3.7
    t = "3675 ---- ---- 17.90B/5.60A 17.90B/5.60A ---- 5.40 - 11.00 .0462 ---- ---- 1 ---- 2 + 1".split()
    settle, delta, _, vol, oi = bg._parse_tail(t[1:])
    assert (settle, delta, vol, oi) == (5.4, 0.0462, 1.0, 2.0)
    for s, oi in [("TOTAL 416 487+ 170", 487), ("TOTAL 416 487 + 170", 487), ("TOTAL 9 0", 9),
                  ("TOTAL 1 38 0", 38), ("TOTAL 2 1- 7", 1), ("TOTAL 5044 40 7483+ 2392", 7483)]:
        assert bg._parse_total(s.split()) == oi, s


def test_black76_roundtrip():
    F, K, T = 4000.0, np.array([3600., 4000., 4400.]), 0.25
    for call in (True, False):
        p = cg.b76_price(F, K, T, 0.22, cg.RATE, call)
        np.testing.assert_allclose(cg.b76_iv(p, F, K, T, cg.RATE, call), 0.22, atol=1e-6)


def test_tv_symbol_and_calendar():
    assert cg.tv_symbol("GCZ6", 2026) == "COMEX:GCZ2026"
    assert cg.tv_symbol("GCG7", 2026) == "COMEX:GCG2027"
    assert gexmap.next_session(dt.date(2026, 11, 6)) == dt.datetime(2026, 11, 9, 13, 30, tzinfo=dt.timezone.utc)
    assert gexmap.next_session(dt.date(2026, 11, 25)) == dt.datetime(2026, 11, 27, 13, 30, tzinfo=dt.timezone.utc)
    # OG last trade dates printed in the real 2026-11-04 bulletin
    assert [cg.og_monthly_expiry(*ym).strftime("%m/%d") for ym in
            [(2026, 12), (2027, 1), (2027, 2), (2027, 3), (2027, 4)]] == \
        ["11/24", "12/28", "01/26", "02/23", "03/24"]
